(()=>{'use strict';const $=id=>document.getElementById(id);const original={number:'KD001',description:'轨道机器人故障',issue:'轨道机器人',device:'机器人',department:'科达（西安）',status:'待关闭',type:'一般性维修',start:'2023-02-06 10:28:56',end:'2023-02-13 10:28:56',owner:'张国栋',handler:'孙国栋',priority:'紧急'};let order={...original};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const panel=(t,body,c='')=>`<section class="panel ${c}"><div class="panel-title"><h2>${t}</h2></div><div class="ticket-detail-body">${body}</div></section>`;const field=(label,value,c='')=>`<div class="ticket-field ${c}"><span>${label}</span><b>${esc(value)}</b></div>`;const fit=()=>document.documentElement.style.setProperty('--scale',Math.min(innerWidth/1920,innerHeight/1080));fit();addEventListener('resize',fit);function clock(){$('clock').textContent=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date());}clock();setInterval(clock,1000);
function render(){$('suite-main').innerHTML=`<div class="ticket-detail-layout"><aside class="ticket-detail-side">${panel('工单档案',`<div class="ticket-number"><span>工单编号</span><strong>${esc(order.number)}</strong></div><div class="ticket-state"><i></i><span>${esc(order.status)}</span></div><div class="ticket-side-fields">${field('部门',order.department)}${field('负责人',order.owner)}${field('处理人',order.handler)}</div>`,'ticket-profile')}${panel('关联设备',`<div class="ticket-equipment-art"><svg viewBox="0 0 240 150" aria-hidden="true"><defs><linearGradient id="eq"><stop stop-color="#3d728c"/><stop offset="1" stop-color="#12334b"/></linearGradient></defs><path d="M32 112l103-35 76 40-104 32Z" fill="#0a2133" stroke="#446c83"/><path d="M58 69l73-25 39 22v51l-73 25-39-23Z" fill="url(#eq)" stroke="#6594ab"/><path d="M58 69l39 23 73-26M97 92v50" fill="none" stroke="#83bbcd"/><path d="M76 59V34l50-16 38 20v25" fill="none" stroke="#56859d" stroke-width="5"/><path d="M106 95l46-16v24l-46 16Z" fill="#082235" stroke="#689db2"/><path d="M114 96l29-10" stroke="#9ddbe3" stroke-width="3"/><path d="M67 84l20 11v19l-20-11Z" fill="#1c455c"/><path d="M20 117l25-9M178 136l35-13" stroke="#79afc4" stroke-width="2"/></svg><span>设备关系示意</span></div>${field('设备',order.device)}${field('关联问题',order.issue)}<a class="ticket-related-link" href="./energy-station-plan.html"><span>查看平面站控示例</span><b>↗</b></a>`,'ticket-equipment')}</aside><div class="ticket-detail-content"><div class="suite-toolbar"><div><h2>维修工单详情</h2><small>${esc(order.number)} / 设备维修任务</small></div><div class="ticket-head-actions"><button class="suite-button" id="reset-order">恢复示例</button><button class="suite-button primary" id="edit-order">编辑工单</button></div></div><div class="ticket-summary-row"><article><span>工单优先级</span><strong class="${order.priority==='紧急'?'urgent-priority':''}">${esc(order.priority)}</strong><i></i></article><article><span>工单类型</span><strong>${esc(order.type)}</strong><i></i></article><article><span>当前状态</span><strong>${esc(order.status)}</strong><i></i></article></div>${panel('故障与设备信息',`<div class="fault-composition"><div class="fault-focus"><div class="fault-lead"><div class="fault-device-mark"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M7 9h18v15H7ZM10 5h12v4M11 14h10M11 18h6M4 13H1M4 20H1M28 13h3M28 20h3M11 27v4M21 27v4" fill="none" stroke="currentColor" stroke-width="1.3"/></svg></div><div><span>工单描述</span><h3>${esc(order.description)}</h3></div></div><div class="fault-association"><span>关联问题</span><b>${esc(order.issue)}</b></div></div><div class="fault-device-context"><div><span>关联设备</span><b>${esc(order.device)}</b></div><div><span>所属部门</span><b>${esc(order.department)}</b></div></div></div>`,'ticket-fault-panel')}${panel('计划与执行信息',`<div class="execution-composition"><div class="execution-dates"><div class="execution-date"><span><i></i>计划开始</span><b>${esc(order.start.split(' ')[0])}</b><small>${esc(order.start.split(' ').slice(1).join(' '))}</small></div><div class="execution-connector"><i></i><span>计划区间</span><i></i></div><div class="execution-date"><span><i></i>计划结束</span><b>${esc(order.end.split(' ')[0])}</b><small>${esc(order.end.split(' ').slice(1).join(' '))}</small></div></div><div class="execution-people"><div><i>${esc(order.owner.slice(0,1))}</i><span>负责人<b>${esc(order.owner)}</b></span></div><div><i>${esc(order.handler.slice(0,1))}</i><span>处理人<b>${esc(order.handler)}</b></span></div></div></div>`,'ticket-plan-panel')}${panel('处理记录',`<table class="ticket-log-table"><thead><tr><th>处理时间</th><th>处理人</th><th>处理内容</th></tr></thead><tbody><tr><td colspan="3"><div class="ticket-log-placeholder"><svg viewBox="0 0 32 32" aria-hidden="true"><path d="M7 3h14l5 5v21H7ZM20 3v7h6M12 15h9M12 20h9M12 25h5" fill="none" stroke="currentColor" stroke-width="1.2"/></svg><span>暂无处理记录</span></div></td></tr></tbody></table>`,'ticket-log-panel')}</div></div>`;$('edit-order').onclick=edit;$('reset-order').onclick=()=>{order={...original};render();toast('已恢复示例工单');};}
let toastTimer;function toast(s){$('toast').textContent=s;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3000);}
function edit(){const input=(l,n)=>`<label>${l}<input name="${n}" value="${esc(order[n])}" required></label>`;const select=(l,n,options)=>`<label>${l}<select name="${n}">${options.map(v=>`<option ${order[n]===v?'selected':''}>${v}</option>`).join('')}</select></label>`;$('dialog-title').textContent='编辑维修工单';$('suite-dialog').className='suite-modal ticket-edit-dialog';$('dialog-content').innerHTML=`<form id="ticket-edit-form"><label>工单编号<input value="${esc(order.number)}" readonly></label>${select('优先级','priority',['紧急','一般'])}<label class="form-wide">工单描述<textarea name="description" required>${esc(order.description)}</textarea></label>${input('关联问题','issue')}${input('设备','device')}${input('部门','department')}${select('状态','status',['待关闭','关闭','待观察','待验收','待处理','上报'])}${select('工单类型','type',['一般性维修','计划性维修','外委性维修'])}${input('负责人','owner')}${input('处理人','handler')}${input('计划开始','start')}${input('计划结束','end')}<p class="edit-help form-wide">此处仅编辑当前演示记录，不写入生产系统。</p><div class="edit-actions form-wide"><button class="suite-button" type="button" id="cancel-edit">取消</button><button class="suite-button primary" type="submit">保存修改</button></div></form>`;$('suite-dialog').showModal();$('cancel-edit').onclick=()=>$('suite-dialog').close();$('ticket-edit-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));if(values.start>values.end){toast('计划结束时间不能早于开始时间');return;}Object.assign(order,values);$('suite-dialog').close();render();toast('工单已更新');};}
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('请在独立页面中使用浏览器全屏。');}};render();})();
